//! Central's text functions for extraction (`central/src/pipeline/extract.ts`, `util.ts`, `docs/render.ts`), ported to
//! cut and match text as JavaScript does: lengths and cuts count UTF-16 code units, `\w` and `\b` are ASCII, `\s` is
//! JavaScript's whitespace, and `.` stops at a carriage return. A port that counted bytes or chars would cut non-ASCII
//! text elsewhere and send other prompts. Fixtures generated by central's own functions check each one
//! (`tests/fixtures/js-port/`).

use regex::Regex;
use std::sync::OnceLock;

/// The longest chunk extraction reads at once, in UTF-16 code units (`MAX_CHUNK`).
#[cfg_attr(not(test), allow(dead_code))]
pub const MAX_CHUNK: usize = 30_000;
/// A chunk whose extract answer ran out of room is split only when at least this long (`MIN_SPLIT`).
pub const MIN_SPLIT: usize = 2_000;

/// JavaScript's `\s`.
pub fn js_space(c: char) -> bool {
    matches!(
        c,
        '\t' | '\n' | '\u{0B}' | '\u{0C}' | '\r' | ' ' | '\u{A0}' | '\u{1680}' | '\u{2000}'
            ..='\u{200A}'
                | '\u{2028}'
                | '\u{2029}'
                | '\u{202F}'
                | '\u{205F}'
                | '\u{3000}'
                | '\u{FEFF}'
    )
}

/// `String.prototype.trim`.
pub fn js_trim(s: &str) -> &str {
    s.trim_matches(js_space)
}

/// `.length`: UTF-16 code units.
pub fn len16(s: &str) -> usize {
    s.chars().map(char::len_utf16).sum()
}

/// The byte index of UTF-16 offset `n` (clamped to the end). An offset inside a surrogate pair moves past the pair:
/// JavaScript would cut the pair in half, which no valid text can hold.
fn byte_at16(s: &str, n: usize) -> usize {
    let mut units = 0;
    for (i, c) in s.char_indices() {
        if units >= n {
            return i;
        }
        units += c.len_utf16();
    }
    s.len()
}

/// `.slice(0, n)`.
pub fn head16(s: &str, n: usize) -> &str {
    &s[..byte_at16(s, n)]
}

/// `.slice(n)`.
pub fn tail16(s: &str, n: usize) -> &str {
    &s[byte_at16(s, n)..]
}

fn re(cell: &'static OnceLock<Regex>, pattern: &str) -> &'static Regex {
    cell.get_or_init(|| Regex::new(pattern).expect("a valid pattern"))
}

macro_rules! regex {
    ($p:expr) => {{
        static R: OnceLock<Regex> = OnceLock::new();
        re(&R, $p)
    }};
}

/// `/^#{1,4}\s/`.
fn chunk_heading(line: &str) -> bool {
    let n = line.bytes().take_while(|b| *b == b'#').count();
    (1..=4).contains(&n) && line[n..].chars().next().is_some_and(js_space)
}

/// `chunk(notes, max)`: at most `max` UTF-16 units each, at a heading when the chunk is past 60%, else at a line; a
/// line longer than `max` is cut.
pub fn chunk(notes: &str, max: usize) -> Vec<String> {
    if len16(notes) <= max {
        return vec![notes.to_string()];
    }
    let mut out = Vec::new();
    let mut cur: Vec<&str> = Vec::new();
    let mut size = 0usize;
    for line in notes.split('\n') {
        let heading = chunk_heading(line);
        let n = len16(line);
        if !cur.is_empty() && (size + n + 1 > max || (heading && size as f64 > max as f64 * 0.6)) {
            out.push(cur.join("\n"));
            cur.clear();
            size = 0;
        }
        let mut s = line;
        loop {
            let n = len16(s);
            if n <= max {
                cur.push(s);
                size += n + 1;
                break;
            }
            out.push(head16(s, max).to_string());
            s = tail16(s, max);
        }
    }
    if !cur.is_empty() {
        out.push(cur.join("\n"));
    }
    out
}

/// `splitChunk(notes)`: two or more pieces of about half the length, losing nothing. A rendered docs change keeps its
/// instructions in every piece (`preambles`: the plain and the word-marked preamble).
pub fn split_chunk(notes: &str, preambles: [&str; 2]) -> Vec<String> {
    let pieces = chunk(notes, len16(notes).div_ceil(2));
    let page = if preambles.iter().any(|p| notes.starts_with(p)) {
        notes.find("\nPage: ").map(|at| {
            let start = at + 1;
            let end = notes[start..].find('\n').map_or(notes.len(), |e| start + e);
            &notes[..end]
        })
    } else {
        None
    };
    let Some(page) = page else { return pieces };
    let (mut section, mut fence, mut opener) = (String::new(), None::<String>, String::new());
    let mut led = Vec::with_capacity(pieces.len());
    for (j, p) in pieces.iter().enumerate() {
        let lead = if j == 0 {
            String::new()
        } else {
            let mut parts = vec![page.to_string(), String::new()];
            if fence.is_some() {
                parts.push(section.clone());
                parts.push(opener.clone());
            }
            parts.join("\n") + "\n"
        };
        for line in p.split('\n') {
            if let Some(f) = &fence {
                if line == f {
                    fence = None;
                }
                continue;
            }
            if line.starts_with("Section: ") {
                section = line.to_string();
            }
            let ticks = line.bytes().take_while(|b| *b == b'`').count();
            if ticks >= 3 && (line.len() == ticks || &line[ticks..] == "diff") {
                fence = Some(line[..ticks].to_string());
                opener = line.to_string();
            }
        }
        led.push(lead + p);
    }
    let whole = len16(notes);
    if led.iter().all(|p| len16(p) < whole) {
        led
    } else {
        pieces
    }
}

// ---- contentFree

const STRUCTURAL_HEADING: &str = r"(?i)^(?:(?:patch|minor|major) changes|what'?s changed|changelog|release notes|view changes on github)?$";
const SECTION_LABEL: &str = r"(?i)^(?:(?:patch|minor|major) changes|what'?s changed|changelog|release notes|bug ?fix(?:es)?|fix(?:es)?|features?|new features|enhancements?|improvements?|chores?|miscellaneous(?: chores)?|misc|other changes|others?|internal|maintenance|refactor(?:ing)?|documentation|docs|dependencies|dependency updates|deps|build(?: system)?|ci|tests?|performance(?: improvements)?|thank you|thanks|authors?|committers?|contributors|new contributors|credits|install(?:ation)?|reverts?)$";
const CREDITS_LABEL: &str =
    r"(?i)^(?:thank you|thanks|authors?|committers?|contributors|new contributors|credits)$";
/// `\w` as JavaScript reads it.
const W: &str = "A-Za-z0-9_";

fn version_token() -> &'static Regex {
    static R: OnceLock<Regex> = OnceLock::new();
    R.get_or_init(|| {
        Regex::new(&format!(
            r"@?[{W}./-]*@[0-9][{W}.+-]*|(?-u:\b)v?[0-9][{W}.+-]*"
        ))
        .unwrap()
    })
}

fn unlink(s: &str) -> String {
    regex!(r"!?\[([^\]]*)\]\([^)]*\)")
        .replace_all(s, "${1}")
        .into_owned()
}

fn strip_urls(s: &str) -> String {
    let s = regex!(
        r"https?://[^\t\n\x0B\x0C\r \xA0\x{1680}\x{2000}-\x{200A}\x{2028}\x{2029}\x{202F}\x{205F}\x{3000}\x{FEFF}]+"
    )
    .replace_all(s, "");
    s.replace("&nbsp;", "")
}

/// Collapses runs of JavaScript whitespace to one space (`.replace(/\s+/g, " ")`).
fn squash(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut space = false;
    for c in s.chars() {
        if js_space(c) {
            if !space {
                out.push(' ');
            }
            space = true;
        } else {
            out.push(c);
            space = false;
        }
    }
    out
}

/// `/^#{1,6}\s+(.*)$/` on one line: the heading text, where `.` stops at a line terminator.
fn heading_text(line: &str) -> Option<&str> {
    let n = line.bytes().take_while(|b| *b == b'#').count();
    if !(1..=6).contains(&n) {
        return None;
    }
    let rest = &line[n..];
    if !rest.chars().next().is_some_and(js_space) {
        return None;
    }
    // `\s+` is greedy but gives back what `(.*)$` cannot take; `.` never matches \r, \u2028, \u2029 (or \n).
    let text = rest.trim_start_matches(js_space);
    let stop = |c: char| matches!(c, '\r' | '\u{2028}' | '\u{2029}');
    if text.contains(stop) {
        // Backtracking can only shorten `\s+`; a terminator in the remainder means no match unless it is inside the
        // whitespace run, which trim_start already consumed.
        return None;
    }
    Some(text)
}

/// Notes with nothing a change record could come from (`contentFree`): no model call is made for them.
pub fn content_free(notes: &str) -> bool {
    no_text(notes) || release_boilerplate(notes)
}

fn has_letter_or_digit(s: &str) -> bool {
    regex!(r"[\p{L}\p{N}]").is_match(s)
}

fn no_text(notes: &str) -> bool {
    let mut deps = false;
    for raw in notes.split('\n') {
        let line = js_trim(raw);
        if line.is_empty() {
            continue;
        }
        let text = strip_urls(&unlink(line));
        if let Some(h) = heading_text(&text) {
            let label = version_token().replace_all(h, "");
            let label = regex!(r"[^\p{L}\p{N}' ]+").replace_all(&label, " ");
            let label = squash(&label);
            if regex!(STRUCTURAL_HEADING).is_match(js_trim(&label)) {
                continue;
            }
            return false;
        }
        if regex!(r"^[-*]?[\s]*Updated dependencies[\s.,:;()#`\\\[\]0-9a-f]*$").is_match(&text) {
            deps = true;
            continue;
        }
        static DEP_LINE: OnceLock<Regex> = OnceLock::new();
        let dep_line = DEP_LINE
            .get_or_init(|| Regex::new(&format!(r"^\s*[-*]\s*@?[{W}./-]+@[{W}.+-]+\s*$")).unwrap());
        if deps && dep_line.is_match(raw) {
            continue;
        }
        deps = false;
        if regex!(r"(?i)^\**\s*Full Changelog\**:?\s*\S*\s*$").is_match(&text) {
            continue;
        }
        if regex!(r"(?i)^[#\s]*View changes on GitHub\s*$").is_match(&text) {
            continue;
        }
        if regex!(r"(?i)^[*_\s]*No (significant )?changes[.!]?[*_\s]*$").is_match(&text) {
            continue;
        }
        if has_letter_or_digit(&text) {
            return false;
        }
    }
    true
}

fn section_label(heading: &str) -> String {
    let s = unlink(heading);
    let s = regex!(r":[a-z_+-]+:").replace_all(&s, " ");
    let s = version_token().replace_all(&s, " ");
    let s = regex!(r"[^\p{L}' ]+").replace_all(&s, " ");
    js_trim(&squash(&s)).to_string()
}

/// Notes whose every line is release boilerplate (`releaseBoilerplate`).
pub fn release_boilerplate(notes: &str) -> bool {
    static PATTERNS: OnceLock<Vec<Regex>> = OnceLock::new();
    let p = PATTERNS.get_or_init(|| {
        [
            // 0: changesets header with hashes or PR numbers, or with the packages inline.
            format!(r"(?i)^[-*+]?\s*(?:[0-9a-f]{{7,40}}:?\s*)?Updated dependencies(?:[\s.,:;()#`\\\[\]0-9a-f]*|:?\s*(?:`?@?[{W}./-]+@[{W}.^~+-]+`?,?\s*)+)$"),
            // 1
            format!(r"^[-*+]\s*`?@?[{W}./-]+@[{W}.^~+-]+`?,?\s*$"),
            // 2
            r"(?i)^[-*+]?\s*The following workspace dependencies were updated\s*$".to_string(),
            // 3
            r"^[-*+]?\s*(?:dev|peer)?[Dd]ependencies\s*$".to_string(),
            // 4: bump x from 1 to 2
            format!(r"(?i)^bump(?:ed|s)?\s+`?[@{W}./-]+`?\s+(?:from\s+`?v?[0-9][{W}.+-]*`?\s+)?to\s+`?v?[0-9][{W}.+-]*`?$"),
            // 5: update dependency x to v3
            format!(r"(?i)^update(?:d|s)?\s+(?:dependency\s+)?`?[@{W}./-]+`?\s+(?:from\s+`?v?[0-9][{W}.+-]*`?\s+)?to\s+`?v?[0-9][{W}.+-]*`?$"),
            // 6: release lines
            format!(r"(?i)^(?:(?:release|version|v)\s*:?\s*v?[0-9][{W}.+-]*|(?:initial|first) release|no updates|nothing to (?:see|report)|no (?:significant |notable |user[- ]facing )?changes(?: in this (?:release|version))?)[.!]?$"),
            // 7: item lead: changesets "#123 `abc1234` Thanks @user! -"
            r"^(?:#[0-9]+\s+)?`?[0-9a-f]{7,40}`?:?\s*(?:Thanks\s+@[A-Za-z0-9_-]+!?\s*-\s*)?".to_string(),
            // 8: "by @user in <url>"
            r"\s+by\s+@[A-Za-z0-9_\[\]-]+(?:\s+in\s*#?[0-9]*)?\s*$".to_string(),
            // 9: "(#123)", "(abc1234)"
            r"(?:\s*\((?:#[0-9]+|[0-9a-f]{7,40})\))+\s*$".to_string(),
            // 10: deps scope
            r"(?i)^(?:\*\*)?(?:(?:chore|build|fix)\()?deps(?:-dev)?\)?:?(?:\*\*)?:?\s*".to_string(),
            // 11
            r"(?i)^(?:chore|build)(?:\([^)]*\))?:\s*".to_string(),
        ]
        .iter()
        .map(|s| Regex::new(s).unwrap())
        .collect()
    });
    let mut credits = false;
    let mut fence = false;
    for raw in notes.split('\n') {
        let line = js_trim(raw);
        if line.is_empty() {
            continue;
        }
        let text_owned = strip_urls(&unlink(line));
        let text = js_trim(&text_owned);
        if regex!(r"^(`{3,}|~{3,})[A-Za-z0-9_-]*$").is_match(line) {
            fence = !fence;
            continue;
        }
        if let Some(b) = regex!(r"^\*\*([^*]+)\*\*:?$").captures(text)
            && regex!(SECTION_LABEL).is_match(&section_label(&b[1]))
        {
            credits = regex!(CREDITS_LABEL).is_match(&section_label(&b[1]));
            continue;
        }
        if let Some(h) = heading_text(text)
            && !fence
        {
            let label = section_label(h);
            if label.is_empty() || regex!(SECTION_LABEL).is_match(&label) {
                credits = regex!(CREDITS_LABEL).is_match(&label);
                continue;
            }
            if !js_trim(&unlink(h)).contains(js_space) {
                continue;
            }
            return false;
        }
        if credits && regex!(r"^[-*+]\s").is_match(line) {
            continue;
        }
        credits = false;
        if !has_letter_or_digit(text) {
            continue;
        }
        if regex!(r"(?i)^\**\s*Full Changelog\**:?\s*\S*\s*$").is_match(text)
            || regex!(r"(?i)^[*_\s]*No (significant )?changes[.!]?[*_\s]*$").is_match(text)
            || regex!(r"(?i)(?-u:\b)version bump only(?-u:\b)").is_match(text)
        {
            continue;
        }
        if regex!(r"^<!--.*-->$").is_match(line)
            || regex!(r"(?i)^<a\s+(name|id)=[^>]*>\s*</a>$").is_match(line)
            || regex!(r"^[-|:\s]+$").is_match(line)
        {
            continue;
        }
        if p[0].is_match(text) || p[1].is_match(text) || p[2].is_match(text) || p[3].is_match(text)
        {
            continue;
        }
        let item = regex!(r"^[-*+]\s*").replace(text, "");
        let item = p[7].replace(&item, "");
        let item = p[8].replace(&item, "");
        let item = p[9].replace(&item, "");
        let item = regex!(r"\s*#[0-9]+\s*$").replace(&item, "");
        let item = js_trim(&item).to_string();
        let bare = p[10].replace(&item, "");
        let bare = p[11].replace(&bare, "");
        if p[4].is_match(&bare) || p[5].is_match(&bare) || p[6].is_match(&item) {
            continue;
        }
        return false;
    }
    true
}

// ---- Locating quotes and cleaning model text

fn norm(s: &str) -> String {
    let s: String = s
        .chars()
        .filter(|c| !matches!(c, '`' | '*' | '_' | '\\'))
        .collect();
    js_trim(&squash(&s)).to_lowercase()
}

/// `locate(notes, quote)`: whether the quote is verbatim in the notes (markup and whitespace folded), and its heading.
pub fn locate(notes: &str, quote: &str) -> (bool, Option<String>) {
    let q = norm(quote);
    if q.is_empty() {
        return (false, None);
    }
    let mut heading: Option<String> = None;
    for line in notes.split('\n') {
        if let Some(h) = heading_text(line) {
            let h: String = h
                .chars()
                .filter(|c| !matches!(c, '`' | '*' | '_'))
                .collect();
            let h = head16(js_trim(&h), 120).to_string();
            if !h.is_empty() {
                heading = Some(h);
            }
        }
        if norm(line).contains(&q) {
            return (true, heading);
        }
    }
    (norm(notes).contains(&q), None)
}

/// `oneLine(s, max)` of central's util.ts: control characters, whitespace and invisible marks become one space, then at
/// most `max` code points, the last an ellipsis.
pub fn one_line(s: &str, max: usize) -> String {
    let blank = |c: char| {
        c.is_control()
            || js_space(c)
            || matches!(c, '\u{200B}'..='\u{200F}' | '\u{202A}'..='\u{202E}' | '\u{2066}'..='\u{2069}' | '\u{FEFF}')
    };
    let mut t = String::with_capacity(s.len());
    let mut run = false;
    for c in s.chars() {
        if blank(c) {
            if !run {
                t.push(' ');
            }
            run = true;
        } else {
            t.push(c);
            run = false;
        }
    }
    let t = js_trim(&t);
    if t.chars().count() <= max {
        return t.to_string();
    }
    let cut: String = t.chars().take(max.saturating_sub(1)).collect();
    format!("{}…", cut.trim_end_matches(js_space))
}

/// `strings(v, max)`: string items only, backticks removed, one line of at most 200, distinct, at most `max`.
pub fn strings(v: Option<&serde_json::Value>, max: usize) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    for x in v.and_then(|v| v.as_array()).into_iter().flatten() {
        let Some(x) = x.as_str() else { continue };
        let s = one_line(&x.replace('`', ""), 200);
        if !s.is_empty() && !out.contains(&s) && out.len() < max {
            out.push(s);
        }
    }
    out
}

/// `words(s, max)`: at most `max` words, an ellipsis when cut.
pub fn words(s: &str, max: usize) -> String {
    let line = one_line(s, 400);
    let w: Vec<&str> = line.split(' ').collect();
    if w.len() <= max {
        return w.join(" ");
    }
    let mut cut = w[..max].join(" ");
    if cut.ends_with([',', ';', ':']) {
        cut.pop();
    }
    cut + "…"
}

/// `cleanSubject`: no backticks or asterisks, no trailing empty call parentheses, one line.
pub fn clean_subject(s: &str) -> String {
    let s: String = s.chars().filter(|c| !matches!(c, '`' | '*')).collect();
    let s =
        regex!(r"\([\t\n\x0B\x0C\r \xA0\x{1680}\x{2000}-\x{200A}\x{2028}\x{2029}\x{202F}\x{205F}\x{3000}\x{FEFF}]*\)$")
            .replace(&s, "");
    one_line(&s, 200)
}

/// The fallback for `subject_kind` when the model gave none: a literal when it looks like code.
pub fn looks_literal(subject: &str) -> bool {
    regex!(r"[._:/()@-]|[a-z][A-Z]").is_match(subject)
}

/// `impactOf`: a guide's impact rating for the section holding a quote ("Likelihood Of Impact: High").
pub fn impact_of(notes: &str, section: Option<&str>) -> Option<String> {
    let section = section?;
    let lines: Vec<&str> = notes.split('\n').collect();
    let starts = |l: &str| regex!(r"^#{1,6}\s+").is_match(l);
    let at = lines.iter().position(|l| {
        if !starts(l) {
            return false;
        }
        let t = regex!(r"^#{1,6}\s+").replace(l, "");
        let t: String = t
            .chars()
            .filter(|c| !matches!(c, '`' | '*' | '_'))
            .collect();
        js_trim(&t).starts_with(section)
    })?;
    for l in &lines[at + 1..] {
        if starts(l) && !regex!(r"(?i)impact").is_match(l) {
            break;
        }
        if let Some(m) =
            regex!(r"(?i)likelihood of impact:?\s*\**\s*(high|medium|low|very low)").captures(l)
        {
            return Some(m[1].to_lowercase());
        }
    }
    None
}

fn removed() -> &'static Regex {
    regex!(r"(?s)\[-(.*?)-\]")
}
fn added() -> &'static Regex {
    regex!(r"(?s)\{\+(.*?)\+\}")
}

/// `markViews`: the page text after a word-marked change, and before it.
pub fn mark_views(notes: &str) -> (String, String) {
    let after = added()
        .replace_all(&removed().replace_all(notes, ""), "${1}")
        .into_owned();
    let before = removed()
        .replace_all(&added().replace_all(notes, ""), "${1}")
        .into_owned();
    (after, before)
}

/// `unmarkQuote`: an evidence quote as page text, the model's copied marks and diff prefixes removed.
pub fn unmark_quote(q: &str) -> String {
    let s: Vec<String> = q
        .split('\n')
        .map(|l| {
            let mut cs = l.chars();
            match (cs.next(), cs.next()) {
                (Some('~' | '+' | '-'), Some(n)) if !js_space(n) => l[1..].to_string(),
                _ => l.to_string(),
            }
        })
        .collect();
    let s = s.join("\n");
    if s.contains("{+") {
        added()
            .replace_all(&removed().replace_all(&s, ""), "${1}")
            .into_owned()
    } else {
        removed().replace_all(&s, "${1}").into_owned()
    }
}

/// `releaseLine`: the major version, or `0.minor` below 1.0.
pub fn release_line(version: &str) -> String {
    let mut it = version.split('.');
    let maj = it.next().unwrap_or("");
    if maj == "0" {
        format!("0.{}", it.next().unwrap_or("0"))
    } else {
        maj.to_string()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;

    pub(crate) fn fixtures() -> Value {
        let p = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests/fixtures/js-port/fixtures.json");
        serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap()
    }

    fn strs(v: &Value) -> Vec<String> {
        v.as_array()
            .unwrap()
            .iter()
            .map(|x| x.as_str().unwrap().to_string())
            .collect()
    }

    #[test]
    fn chunks_are_cut_in_utf16_units_as_central_cuts_them() {
        let f = fixtures();
        assert_eq!(f["min_split"], MIN_SPLIT);
        for (i, c) in f["chunk"].as_array().unwrap().iter().enumerate() {
            let notes = c["notes"].as_str().unwrap();
            let got = chunk(notes, c["max"].as_u64().unwrap() as usize);
            assert_eq!(got, strs(&c["out"]), "chunk case {i}");
        }
        // The cases do cut differently by bytes or chars: the fixture would catch a port that counted either.
        let notes = f["chunk"][1]["notes"].as_str().unwrap();
        assert!(notes.len() != len16(notes) && notes.chars().count() != len16(notes));
    }

    #[test]
    fn split_pieces_match_central_including_docs_preambles() {
        let f = fixtures();
        let e = &crate::prompts::prompts().extract;
        for (i, c) in f["split"].as_array().unwrap().iter().enumerate() {
            let got = split_chunk(
                c["notes"].as_str().unwrap(),
                [&e.docs_preamble_marked, &e.docs_preamble],
            );
            assert_eq!(got, strs(&c["out"]), "split case {i}");
        }
    }

    #[test]
    fn content_free_and_locate_match_central() {
        let f = fixtures();
        for c in f["content_free"].as_array().unwrap() {
            let notes = c["notes"].as_str().unwrap();
            assert_eq!(
                content_free(notes),
                c["out"].as_bool().unwrap(),
                "{notes:?}"
            );
        }
        for c in f["locate"].as_array().unwrap() {
            let (grounded, section) =
                locate(c["notes"].as_str().unwrap(), c["quote"].as_str().unwrap());
            assert_eq!(grounded, c["out"]["grounded"].as_bool().unwrap());
            assert_eq!(section.as_deref(), c["out"]["section"].as_str());
        }
    }

    #[test]
    fn small_helpers_follow_javascript() {
        assert_eq!(len16("a🎉é"), 4);
        assert_eq!(
            head16("a🎉b", 2),
            "a🎉",
            "a cut inside a pair keeps the pair"
        );
        assert_eq!(one_line("  a\u{200B}\n b  ", 10), "a b");
        assert_eq!(one_line("abcdef", 4), "abc…");
        assert_eq!(words("a b c,", 2), "a b…");
        assert_eq!(words("a b, c", 2), "a b…");
        assert_eq!(clean_subject("`after()`"), "after");
        assert_eq!(release_line("0.4.2"), "0.4");
        assert_eq!(release_line("16.1.0"), "16");
        assert_eq!(
            unmark_quote("Default: [-3000.-]{+4000.+}"),
            "Default: 4000."
        );
        assert_eq!(unmark_quote("[-gone-]"), "gone");
        assert_eq!(
            impact_of("## A\n**Likelihood Of Impact: Very Low**", Some("A")).as_deref(),
            Some("very low")
        );
    }
}
